#!/usr/bin/env bash
BASE="/opt/home-network-monitor"; source "$BASE/config.conf"; STATE="$BASE/state/internet.state"; START="$BASE/state/outage-start"; LOG="$BASE/logs/internet.log"; NOW="$(date "+%Y-%m-%d %H:%M:%S")"; CURRENT="down"; ping -c 2 -W 3 1.1.1.1 >/dev/null 2>&1 && CURRENT="up"; [[ "$CURRENT" == "down" ]] && ping -c 2 -W 3 8.8.8.8 >/dev/null 2>&1 && CURRENT="up"; PREVIOUS="$(cat "$STATE" 2>/dev/null || echo unknown)"; echo "$CURRENT" > "$STATE"; echo "$NOW,${CURRENT^^}" >> "$LOG"; if [[ "$CURRENT" == "down" && "$PREVIOUS" != "down" ]]; then date +%s > "$START"; elif [[ "$CURRENT" == "up" && "$PREVIOUS" == "down" ]]; then BEGAN="$(cat "$START" 2>/dev/null || date +%s)"; MINUTES=$((($(date +%s)-BEGAN)/60)); curl -fsS --max-time 15 -X POST "https://api.telegram.org/bot${BOT_TOKEN}/sendMessage" -d "chat_id=${CHAT_ID}" --data-urlencode "text=🟢 Home internet restored. Approximate downtime: ${MINUTES} minute(s). Restored: ${NOW}" >/dev/null || true; rm -f "$START"; fi
